// ─── DDL ─────────────────────────────────────────────────────────────────────

const DDL = `
  CREATE UNIQUE INDEX IF NOT EXISTS idx_responses_user_title
    ON responses(user_id, title);

  CREATE TABLE IF NOT EXISTS lenders (
    id           SERIAL PRIMARY KEY,
    user_id      INTEGER REFERENCES users(id),
    company_name TEXT NOT NULL,
    address      TEXT,
    city         TEXT,
    province     TEXT,
    postal_code  TEXT,
    contact_name TEXT,
    email        TEXT,
    phone        TEXT,
    notes        TEXT,
    source       TEXT DEFAULT 'cral_import',
    created_at   TIMESTAMPTZ DEFAULT NOW()
  );

  CREATE UNIQUE INDEX IF NOT EXISTS idx_lenders_user_company
    ON lenders(user_id, company_name);

  ALTER TABLE orders ADD COLUMN IF NOT EXISTS lender_id INTEGER REFERENCES lenders(id);
`;

// ─── SEED FUNCTIONS ───────────────────────────────────────────────────────────

async function seedResponses(client) {
  const neighbourhoodRows = NEIGHBOURHOOD_RESPONSES.map(r => ({ ...r, category: 'neighbourhood' }));
  const allResponses = [...neighbourhoodRows, ...STANDARD_RESPONSES];
  let inserted = 0;
  for (const r of allResponses) {
    const result = await client.query(
      `INSERT INTO responses (user_id, category, title, content)
       VALUES ($1, $2, $3, $4)
       ON CONFLICT (user_id, title) DO NOTHING`,
      [USER_ID, r.category, r.title, r.content]
    );
    if (result.rowCount > 0) inserted++;
  }
  console.log(`  Responses: ${inserted} inserted, ${allResponses.length - inserted} already existed.`);
}

async function seedLenders(client) {
  let inserted = 0;
  for (const l of LENDERS) {
    const result = await client.query(
      `INSERT INTO lenders (user_id, company_name, address, city, province, postal_code, source)
       VALUES ($1, $2, $3, $4, $5, $6, 'cral_import')
       ON CONFLICT (user_id, company_name) DO NOTHING`,
      [USER_ID, l.company_name, l.address || null, l.city || null, l.province || null, l.postal_code || null]
    );
    if (result.rowCount > 0) inserted++;
  }
  console.log(`  Lenders: ${inserted} inserted, ${LENDERS.length - inserted} already existed.`);
}

async function seedClients(client) {
  let inserted = 0;
  for (const c of CLIENTS) {
    const result = await client.query(
      `INSERT INTO clients (user_id, client_code, company_name, contact_name, email, phone)
       VALUES ($1, $2, $3, $4, $5, $6)
       ON CONFLICT (user_id, client_code) DO NOTHING`,
      [USER_ID, c.client_code, c.company_name, c.contact_name || null, c.email || null, c.phone || null]
    );
    if (result.rowCount > 0) inserted++;
  }
  console.log(`  Clients: ${inserted} inserted, ${CLIENTS.length - inserted} already existed.`);
}

// ─── MAIN ─────────────────────────────────────────────────────────────────────

async function main() {
  const client = await pool.connect();
  try {
    await client.query('BEGIN');

    console.log('Running DDL...');
    await client.query(DDL);
    console.log('  lenders table, indexes, orders.lender_id: OK');

    console.log('Seeding data...');
    await seedResponses(client);
    await seedLenders(client);
    await seedClients(client);

    await client.query('COMMIT');
    console.log(`Done. Totals attempted: ${NEIGHBOURHOOD_RESPONSES.length + STANDARD_RESPONSES.length} responses, ${LENDERS.length} lenders, ${CLIENTS.length} clients.`);
  } catch (err) {
    await client.query('ROLLBACK');
    console.error('Seed failed — rolled back:', err.message);
    process.exit(1);
  } finally {
    client.release();
    await pool.end();
  }
}

main();
